// Страница каталога для друзей. Запуск: node design/prototype/friends/friends.test.js [shots]
const {chromium}=require('playwright');const path=require('path');
const URL0='file://'+path.join(__dirname,'index.html');const OUT=path.join(__dirname,'..','..','screenshots')+'/';const shots=process.argv[2]==='shots';
const UA='Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1';
const GID='0123456789abcdef0123456789abcdef';
(async()=>{const b=await chromium.launch();let fails=0;
const V=[['телефон 390×844',{viewport:{width:390,height:844},isMobile:true,hasTouch:true,userAgent:UA},'phone-'],['ПК 1440×900',{viewport:{width:1440,height:900}},'']];
for(const th of (shots?['dark','light']:['dark']))for(const [vn,o,k] of V){const ctx=await b.newContext({...o,colorScheme:th});const p=await ctx.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));p.on('dialog',d=>{errs.push('dialog '+d.message());d.dismiss()});
 const ev=(f,a)=>p.evaluate(f,a);const open=async h=>{await p.goto(URL0+h);await p.waitForTimeout(300)};
 const click=async s=>{const l=p.locator(s).first();if(o.hasTouch)await l.tap({timeout:3000});else await l.click({timeout:3000});await p.waitForTimeout(150)};
 const shot=async n=>{if(shots)await p.screenshot({path:OUT+n+'-'+k+th+'.png'})};
 const res=[];const T=async(n,f)=>{try{res.push([n,(await f())?'OK':'FAIL'])}catch(e){res.push([n,'FAIL '+e.message.split('\n')[0].slice(0,90)])}};
 await T('Каталог: шапка, «Обновлено», вкладки со счётчиками',async()=>{await open('#demo');await shot('170-friends-current');return await ev(()=>/Каталог · Юки/.test(document.querySelector('h1').textContent)&&/Обновлено/.test(document.querySelector('.top').textContent)&&document.querySelectorAll('.tab').length===7&&document.querySelector('.tab[aria-selected=true] .c').textContent==='2')});
 await T('Вкладки: Просмотрено 3, Понравилось 3, Заметки 4',async()=>await ev(()=>{const c=l=>[...document.querySelectorAll('.tab')].find(t=>t.textContent.includes(l)).querySelector('.c').textContent;return c('Просмотрено')==='3'&&c('Понравилось')==='3'&&c('Заметки')==='4'&&c('Брошено')==='1'}));
 await T('Оценка с источником',async()=>await ev(()=>[...document.querySelectorAll('.row .score')].map(e=>e.textContent).join('|')==='8,8Shiki|8,4AL'));
 await T('Сортировка по дате',async()=>{await p.selectOption('#sort','date');return await ev(()=>document.querySelector('.row .name').textContent==='Дандадан')});
 await T('В планах: 18+ с пометкой, не скрыт',async()=>{await click('.tab:nth-child(3)');await shot('171-friends-planning-adult');return await ev(()=>[...document.querySelectorAll('.row')].some(r=>/Пример тайтла 18\+/.test(r.textContent)&&r.querySelector('.adult')))});
 await T('Понравилось',async()=>{await click('.tab:nth-child(4)');await shot('172-friends-favorites');return await ev(()=>document.querySelectorAll('.row').length===3&&[...document.querySelectorAll('.row')].every(r=>r.querySelector('.heart')))});
 await T('Заметки: вердикт и итог',async()=>{await click('.tab:nth-child(7)');await shot('173-friends-notes');return await ev(()=>document.querySelectorAll('.row').length===4&&document.querySelectorAll('.row .verdict').length===4)});
 await T('Поиск',async()=>{await click('.tab:nth-child(2)');await p.locator('#q').fill('стал');await p.waitForTimeout(150);const one=await ev(()=>document.querySelectorAll('.row').length===1);await p.locator('#q').fill('xyz');await p.waitForTimeout(150);await shot('174-friends-search-empty');const none=await ev(()=>/Ничего не нашлось/.test(document.querySelector('.state').textContent));await p.locator('#q').fill('');return one&&none});
 await T('Карточка: оценка, статус, сердце, заметка, моменты, трейлер',async()=>{await open('#demo-card');await shot('175-friends-card');return await ev(()=>{const s=document.querySelector('.sheet').textContent;return /8,4/.test(s)&&/AniList/.test(s)&&/Смотрю/.test(s)&&/Понравилось/.test(s)&&/Советует/.test(s)&&/Погоня Турбо-бабки/.test(s)&&!!document.querySelector('.sheet a[href^="https://www.youtube.com"]')})});
 await T('Карточка закрывается',async()=>{await click('.sheet .iconbtn');return await ev(()=>!document.querySelector('.sheet'))});
 await T('Карточка брошенного: причины',async()=>{await open('#demo-carddrop');await shot('176-friends-card-dropped');return await ev(()=>/Почему бросил/.test(document.querySelector('.sheet').textContent)&&document.querySelectorAll('.sheet .chip').length===2)});
 await T('Загрузка',async()=>{await open('#demo-loading');await shot('177-friends-loading');return await ev(()=>document.querySelectorAll('.skel').length>=6)});
 await T('Пустой каталог',async()=>{await open('#demo-empty');await shot('178-friends-empty');return await ev(()=>/Каталог пока пуст/.test(document.body.textContent))});
 await T('Ссылка недействительна',async()=>{await open('#demo-notfound');await shot('179-friends-notfound');return await ev(()=>/Ссылка недействительна/.test(document.body.textContent))});
 await T('Ошибка сети с «Повторить»',async()=>{await open('#demo-net');return await ev(()=>/Не удалось загрузить/.test(document.body.textContent)&&/Повторить/.test(document.body.textContent))});
 await T('Без параметра — «Вставьте ссылку на каталог»',async()=>{await open('');await shot('180-friends-paste');return await ev(()=>/Вставьте ссылку на каталог/.test(document.body.textContent))});
 await T('Неверная ссылка в поле — подсказка',async()=>{await p.locator('#link').fill('привет');await click('button[type=submit]');return await ev(()=>/не похоже на ссылку/.test(document.querySelector('.err').textContent))});
 // настоящая загрузка: подменяем ответ GitHub API
 await T('?g=<id>: загрузка share.json из Gist',async()=>{const demo=await (async()=>{await open('#demo');return ev(()=>DEMO)})();await p.route('https://api.github.com/gists/*',r=>r.fulfill({status:200,contentType:'application/json',headers:{'access-control-allow-origin':'*'},body:JSON.stringify({files:{'share.json':{content:JSON.stringify(demo),truncated:false}}})}));await p.goto(URL0+'?g='+GID);await p.waitForTimeout(500);await p.unroute('https://api.github.com/gists/*');return await ev(()=>/Каталог · Юки/.test(document.querySelector('h1').textContent)&&document.querySelectorAll('.row').length===2)});
 await T('?g=<id>: 404 → «Ссылка недействительна»',async()=>{await p.route('https://api.github.com/gists/*',r=>r.fulfill({status:404,headers:{'access-control-allow-origin':'*'},body:'{}'}));await p.goto(URL0+'?g='+GID);await p.waitForTimeout(400);await p.unroute('https://api.github.com/gists/*');return await ev(()=>/Ссылка недействительна/.test(document.body.textContent))});
 await T('?g=мусор → «Ссылка недействительна» без запроса',async()=>{let hit=false;await p.route('https://api.github.com/**',r=>{hit=true;r.abort()});await p.goto(URL0+'?g=..%2F..%2Fevil');await p.waitForTimeout(300);await p.unroute('https://api.github.com/**');return !hit&&await ev(()=>/Ссылка недействительна/.test(document.body.textContent))});
 await T('Безопасность: HTML и javascript: из share.json не исполняются',async()=>{const evil={titles:[{title:{ru:'<img src=x onerror=alert(1)>'},trailer:'javascript:alert(2)',cover:'javascript:alert(3)',status:'CURRENT',note:{summary:'<b>x</b>'}}]};await p.route('https://api.github.com/gists/*',r=>r.fulfill({status:200,contentType:'application/json',headers:{'access-control-allow-origin':'*'},body:JSON.stringify({files:{'share.json':{content:JSON.stringify(evil)}}})}));await p.goto(URL0+'?g='+GID);await p.waitForTimeout(400);await p.unroute('https://api.github.com/gists/*');await click('.row');return await ev(()=>!document.querySelector('.row img')&&/<img src=x/.test(document.querySelector('.row .name').textContent)&&!document.querySelector('.sheet a')&&!document.querySelector('.sum b'))&&!errs.some(e=>/dialog/.test(e))});
 await T('Нет горизонтальной прокрутки',async()=>{await open('#demo');return await ev(()=>document.documentElement.scrollWidth<=innerWidth)});
 const bad=res.filter(r=>r[1]!=='OK');fails+=bad.length;console.log(th,vn,bad.length?bad:'все '+res.length+' OK',errs);await ctx.close();}
await b.close();process.exitCode=fails?1:0;})();
